pub struct MDELevelBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> MDELevelBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_SET_EPOCH_MS(&mut self, SET_EPOCH_MS: i64) {
        self.fbb_.push_slot::<i64>(MDELevel::VT_SET_EPOCH_MS, SET_EPOCH_MS, 0);
    }

    #[inline]
    pub fn add_SMA_KM(&mut self, SMA_KM: f64) {
        self.fbb_.push_slot::<f64>(MDELevel::VT_SMA_KM, SMA_KM, 0.0);
    }

    #[inline]
    pub fn add_LEVEL_M_S(&mut self, LEVEL_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDELevel::VT_LEVEL_M_S, LEVEL_M_S, 0.0);
    }

    #[inline]
    pub fn add_SIGMA_M_S(&mut self, SIGMA_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDELevel::VT_SIGMA_M_S, SIGMA_M_S, 0.0);
    }

    #[inline]
    pub fn add_PLANE_M_S(&mut self, PLANE_M_S: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDELevel::VT_PLANE_M_S, PLANE_M_S);
    }

    #[inline]
    pub fn add_PLANE_SIGMA_M_S(&mut self, PLANE_SIGMA_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDELevel::VT_PLANE_SIGMA_M_S, PLANE_SIGMA_M_S, 0.0);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> MDELevelBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        MDELevelBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<MDELevel<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

