impl MDEEvidenceT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<MDEEvidence<'b>> {
        let DETECTOR = self.DETECTOR;
        let TIME_MS = self.TIME_MS;
        let PAIR_INDEX = self.PAIR_INDEX;
        let STEP_IN_TRACK_M_S = self.STEP_IN_TRACK_M_S;
        let STEP_PLANE_M_S = self.STEP_PLANE_M_S;
        let THRESHOLD_IN_TRACK_M_S = self.THRESHOLD_IN_TRACK_M_S;
        let THRESHOLD_PLANE_M_S = self.THRESHOLD_PLANE_M_S;
        let CROSSING_AT_EDGE = self.CROSSING_AT_EDGE;
        let SPAN_START_MS = self.SPAN_START_MS;
        let SPAN_STOP_MS = self.SPAN_STOP_MS;
        let GLR_STATISTIC = self.GLR_STATISTIC;
        let STEP_M_S = self.STEP_M_S;
        let STEP_SD_M_S = self.STEP_SD_M_S;
        let SIGMA_M_S = self.SIGMA_M_S;
        let TREND_M_S_PER_DAY = self.TREND_M_S_PER_DAY;
        let OLD_LEVEL_SET_MS = self.OLD_LEVEL_SET_MS;
        let NEW_LEVEL_SET_MS = self.NEW_LEVEL_SET_MS;
        let TIME_BASIS = self.TIME_BASIS;
        let PLANE_GLR_STATISTIC = self.PLANE_GLR_STATISTIC;
        let PLANE_STEP_M_S = self.PLANE_STEP_M_S;
        let RATE_CHANGE_M_S_PER_DAY = self.RATE_CHANGE_M_S_PER_DAY;
        let RATE_CHANGE_SD = self.RATE_CHANGE_SD;
        let TREND_BEFORE_M_S_PER_DAY = self.TREND_BEFORE_M_S_PER_DAY;
        let COMPONENTS = self.COMPONENTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let KEPT = self.KEPT;
        MDEEvidence::create(_fbb, &MDEEvidenceArgs{
            DETECTOR,
            TIME_MS,
            PAIR_INDEX,
            STEP_IN_TRACK_M_S,
            STEP_PLANE_M_S,
            THRESHOLD_IN_TRACK_M_S,
            THRESHOLD_PLANE_M_S,
            CROSSING_AT_EDGE,
            SPAN_START_MS,
            SPAN_STOP_MS,
            GLR_STATISTIC,
            STEP_M_S,
            STEP_SD_M_S,
            SIGMA_M_S,
            TREND_M_S_PER_DAY,
            OLD_LEVEL_SET_MS,
            NEW_LEVEL_SET_MS,
            TIME_BASIS,
            PLANE_GLR_STATISTIC,
            PLANE_STEP_M_S,
            RATE_CHANGE_M_S_PER_DAY,
            RATE_CHANGE_SD,
            TREND_BEFORE_M_S_PER_DAY,
            COMPONENTS,
            KEPT,
        })
    }
}

