    pub const VT_IN_TRACK_FIRED: ::flatbuffers::VOffsetT = 14;
    pub const VT_CROSS_TRACK_FIRED: ::flatbuffers::VOffsetT = 16;
    pub const VT_RAW_IN_TRACK_M_S: ::flatbuffers::VOffsetT = 18;
    pub const VT_RAW_CROSS_TRACK_M_S: ::flatbuffers::VOffsetT = 20;
    pub const VT_DELTA_SMA_KM: ::flatbuffers::VOffsetT = 22;
