    pub const VT_ACCEL_CHANGE_M_S2: ::flatbuffers::VOffsetT = 34;
    pub const VT_MNV_ID: ::flatbuffers::VOffsetT = 36;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        MDEEvent { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args MDEEventArgs<'args>
    ) -> ::flatbuffers::WIPOffset<MDEEvent<'bldr>> {
        let mut builder = MDEEventBuilder::new(_fbb);
        builder.add_ACCEL_CHANGE_M_S2(args.ACCEL_CHANGE_M_S2);
        builder.add_SEPARATION_KM(args.SEPARATION_KM);
        builder.add_DELTA_SMA_KM(args.DELTA_SMA_KM);
        builder.add_RAW_CROSS_TRACK_M_S(args.RAW_CROSS_TRACK_M_S);
        builder.add_RAW_IN_TRACK_M_S(args.RAW_IN_TRACK_M_S);
        builder.add_CROSS_TRACK_M_S(args.CROSS_TRACK_M_S);
        builder.add_IN_TRACK_M_S(args.IN_TRACK_M_S);
        builder.add_TIME_MS(args.TIME_MS);
        if let Some(x) = args.MNV_ID { builder.add_MNV_ID(x); }
        if let Some(x) = args.EVIDENCE { builder.add_EVIDENCE(x); }
        builder.add_BLOCK_AFTER(args.BLOCK_AFTER);
        builder.add_BLOCK_BEFORE(args.BLOCK_BEFORE);
        builder.add_TIME_FROM_CROSSING(args.TIME_FROM_CROSSING);
        builder.add_CROSS_TRACK_FIRED(args.CROSS_TRACK_FIRED);
        builder.add_IN_TRACK_FIRED(args.IN_TRACK_FIRED);
        builder.add_CHARACTERIZATION(args.CHARACTERIZATION);
        builder.add_DETECTOR(args.DETECTOR);
        builder.finish()
    }

    pub fn unpack(&self) -> MDEEventT {
        let DETECTOR = self.DETECTOR();
        let TIME_MS = self.TIME_MS();
        let CHARACTERIZATION = self.CHARACTERIZATION();
        let IN_TRACK_M_S = self.IN_TRACK_M_S();
        let CROSS_TRACK_M_S = self.CROSS_TRACK_M_S();
        let IN_TRACK_FIRED = self.IN_TRACK_FIRED();
        let CROSS_TRACK_FIRED = self.CROSS_TRACK_FIRED();
        let RAW_IN_TRACK_M_S = self.RAW_IN_TRACK_M_S();
        let RAW_CROSS_TRACK_M_S = self.RAW_CROSS_TRACK_M_S();
        let DELTA_SMA_KM = self.DELTA_SMA_KM();
        let SEPARATION_KM = self.SEPARATION_KM();
        let TIME_FROM_CROSSING = self.TIME_FROM_CROSSING();
        let BLOCK_BEFORE = self.BLOCK_BEFORE();
        let BLOCK_AFTER = self.BLOCK_AFTER();
        let EVIDENCE = self.EVIDENCE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let ACCEL_CHANGE_M_S2 = self.ACCEL_CHANGE_M_S2();
        let MNV_ID = self.MNV_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        MDEEventT {
            DETECTOR,
            TIME_MS,
            CHARACTERIZATION,
            IN_TRACK_M_S,
            CROSS_TRACK_M_S,
            IN_TRACK_FIRED,
            CROSS_TRACK_FIRED,
            RAW_IN_TRACK_M_S,
            RAW_CROSS_TRACK_M_S,
            DELTA_SMA_KM,
            SEPARATION_KM,
            TIME_FROM_CROSSING,
            BLOCK_BEFORE,
            BLOCK_AFTER,
            EVIDENCE,
            ACCEL_CHANGE_M_S2,
            MNV_ID,
        }
    }

