impl ::flatbuffers::Verifiable for MDEEvent<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<mdeDetector>("DETECTOR", Self::VT_DETECTOR, false)?
            .visit_field::<i64>("TIME_MS", Self::VT_TIME_MS, false)?
            .visit_field::<maneuverCharacterization>("CHARACTERIZATION", Self::VT_CHARACTERIZATION, false)?
            .visit_field::<f64>("IN_TRACK_M_S", Self::VT_IN_TRACK_M_S, false)?
            .visit_field::<f64>("CROSS_TRACK_M_S", Self::VT_CROSS_TRACK_M_S, false)?
            .visit_field::<bool>("IN_TRACK_FIRED", Self::VT_IN_TRACK_FIRED, false)?
            .visit_field::<bool>("CROSS_TRACK_FIRED", Self::VT_CROSS_TRACK_FIRED, false)?
            .visit_field::<f64>("RAW_IN_TRACK_M_S", Self::VT_RAW_IN_TRACK_M_S, false)?
            .visit_field::<f64>("RAW_CROSS_TRACK_M_S", Self::VT_RAW_CROSS_TRACK_M_S, false)?
            .visit_field::<f64>("DELTA_SMA_KM", Self::VT_DELTA_SMA_KM, false)?
            .visit_field::<f64>("SEPARATION_KM", Self::VT_SEPARATION_KM, false)?
            .visit_field::<bool>("TIME_FROM_CROSSING", Self::VT_TIME_FROM_CROSSING, false)?
            .visit_field::<u32>("BLOCK_BEFORE", Self::VT_BLOCK_BEFORE, false)?
            .visit_field::<u32>("BLOCK_AFTER", Self::VT_BLOCK_AFTER, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<MDEEvidence>>("EVIDENCE", Self::VT_EVIDENCE, false)?
            .visit_field::<f64>("ACCEL_CHANGE_M_S2", Self::VT_ACCEL_CHANGE_M_S2, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("MNV_ID", Self::VT_MNV_ID, false)?
            .finish();
        Ok(())
    }
}

