pub struct MDEEventBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> MDEEventBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_DETECTOR(&mut self, DETECTOR: mdeDetector) {
        self.fbb_.push_slot::<mdeDetector>(MDEEvent::VT_DETECTOR, DETECTOR, mdeDetector::Unspecified);
    }

    #[inline]
    pub fn add_TIME_MS(&mut self, TIME_MS: i64) {
        self.fbb_.push_slot::<i64>(MDEEvent::VT_TIME_MS, TIME_MS, 0);
    }

    #[inline]
    pub fn add_CHARACTERIZATION(&mut self, CHARACTERIZATION: maneuverCharacterization) {
        self.fbb_.push_slot::<maneuverCharacterization>(MDEEvent::VT_CHARACTERIZATION, CHARACTERIZATION, maneuverCharacterization::UNKNOWN);
    }

    #[inline]
    pub fn add_IN_TRACK_M_S(&mut self, IN_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_IN_TRACK_M_S, IN_TRACK_M_S, 0.0);
    }

    #[inline]
    pub fn add_CROSS_TRACK_M_S(&mut self, CROSS_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_CROSS_TRACK_M_S, CROSS_TRACK_M_S, 0.0);
    }

    #[inline]
    pub fn add_IN_TRACK_FIRED(&mut self, IN_TRACK_FIRED: bool) {
        self.fbb_.push_slot::<bool>(MDEEvent::VT_IN_TRACK_FIRED, IN_TRACK_FIRED, false);
    }

    #[inline]
    pub fn add_CROSS_TRACK_FIRED(&mut self, CROSS_TRACK_FIRED: bool) {
        self.fbb_.push_slot::<bool>(MDEEvent::VT_CROSS_TRACK_FIRED, CROSS_TRACK_FIRED, false);
    }

    #[inline]
    pub fn add_RAW_IN_TRACK_M_S(&mut self, RAW_IN_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_RAW_IN_TRACK_M_S, RAW_IN_TRACK_M_S, 0.0);
    }

    #[inline]
    pub fn add_RAW_CROSS_TRACK_M_S(&mut self, RAW_CROSS_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_RAW_CROSS_TRACK_M_S, RAW_CROSS_TRACK_M_S, 0.0);
    }

    #[inline]
    pub fn add_DELTA_SMA_KM(&mut self, DELTA_SMA_KM: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_DELTA_SMA_KM, DELTA_SMA_KM, 0.0);
    }

    #[inline]
    pub fn add_SEPARATION_KM(&mut self, SEPARATION_KM: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_SEPARATION_KM, SEPARATION_KM, 0.0);
    }

    #[inline]
    pub fn add_TIME_FROM_CROSSING(&mut self, TIME_FROM_CROSSING: bool) {
        self.fbb_.push_slot::<bool>(MDEEvent::VT_TIME_FROM_CROSSING, TIME_FROM_CROSSING, false);
    }

    #[inline]
    pub fn add_BLOCK_BEFORE(&mut self, BLOCK_BEFORE: u32) {
        self.fbb_.push_slot::<u32>(MDEEvent::VT_BLOCK_BEFORE, BLOCK_BEFORE, 0);
    }

    #[inline]
    pub fn add_BLOCK_AFTER(&mut self, BLOCK_AFTER: u32) {
        self.fbb_.push_slot::<u32>(MDEEvent::VT_BLOCK_AFTER, BLOCK_AFTER, 0);
    }

    #[inline]
    pub fn add_EVIDENCE(&mut self, EVIDENCE: ::flatbuffers::WIPOffset<MDEEvidence<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<MDEEvidence>>(MDEEvent::VT_EVIDENCE, EVIDENCE);
    }

    #[inline]
    pub fn add_ACCEL_CHANGE_M_S2(&mut self, ACCEL_CHANGE_M_S2: f64) {
        self.fbb_.push_slot::<f64>(MDEEvent::VT_ACCEL_CHANGE_M_S2, ACCEL_CHANGE_M_S2, f64::NAN);
    }

    #[inline]
    pub fn add_MNV_ID(&mut self, MNV_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDEEvent::VT_MNV_ID, MNV_ID);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> MDEEventBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        MDEEventBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<MDEEvent<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

