pub struct MDEVersionChangeBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> MDEVersionChangeBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_OLDER(&mut self, OLDER: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDEVersionChange::VT_OLDER, OLDER);
    }

    #[inline]
    pub fn add_NEWER(&mut self, NEWER: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDEVersionChange::VT_NEWER, NEWER);
    }

    #[inline]
    pub fn add_WITHIN(&mut self, WITHIN: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDEVersionChange::VT_WITHIN, WITHIN);
    }

    #[inline]
    pub fn add_MODE(&mut self, MODE: mdeComparisonMode) {
        self.fbb_.push_slot::<mdeComparisonMode>(MDEVersionChange::VT_MODE, MODE, mdeComparisonMode::Unspecified);
    }

    #[inline]
    pub fn add_DETAIL(&mut self, DETAIL: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(MDEVersionChange::VT_DETAIL, DETAIL);
    }

    #[inline]
    pub fn add_WINDOW_START_MS(&mut self, WINDOW_START_MS: i64) {
        self.fbb_.push_slot::<i64>(MDEVersionChange::VT_WINDOW_START_MS, WINDOW_START_MS, 0);
    }

    #[inline]
    pub fn add_WINDOW_STOP_MS(&mut self, WINDOW_STOP_MS: i64) {
        self.fbb_.push_slot::<i64>(MDEVersionChange::VT_WINDOW_STOP_MS, WINDOW_STOP_MS, 0);
    }

    #[inline]
    pub fn add_DELTA_SMA_KM(&mut self, DELTA_SMA_KM: f64) {
        self.fbb_.push_slot::<f64>(MDEVersionChange::VT_DELTA_SMA_KM, DELTA_SMA_KM, f64::NAN);
    }

    #[inline]
    pub fn add_IN_TRACK_M_S(&mut self, IN_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEVersionChange::VT_IN_TRACK_M_S, IN_TRACK_M_S, f64::NAN);
    }

    #[inline]
    pub fn add_CROSS_TRACK_M_S(&mut self, CROSS_TRACK_M_S: f64) {
        self.fbb_.push_slot::<f64>(MDEVersionChange::VT_CROSS_TRACK_M_S, CROSS_TRACK_M_S, f64::NAN);
    }

    #[inline]
    pub fn add_GAP_S(&mut self, GAP_S: f64) {
        self.fbb_.push_slot::<f64>(MDEVersionChange::VT_GAP_S, GAP_S, f64::NAN);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> MDEVersionChangeBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        MDEVersionChangeBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<MDEVersionChange<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

