    pub const VT_POST: ::flatbuffers::VOffsetT = 20;
    pub const VT_WINDOW_START_MS: ::flatbuffers::VOffsetT = 22;
    pub const VT_WINDOW_STOP_MS: ::flatbuffers::VOffsetT = 24;
